const paths={book:'M3 4q5-2 9 1 4-3 9-1v16q-5-2-9 1-4-3-9-1z M12 5v16',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',speaker:'M3 9h4l5-4v14l-5-4H3z M16 8q4 4 0 8 M19 5q7 7 0 14',check:'M5 12l4 4L19 6',science:'M9 3h6 M10 3v7L4 20h16l-6-10V3 M8 14h8',math:'M5 3h14v18H5z M8 7h8 M8 12h2 M14 12h2 M8 16h2 M14 16h2',english:'M3 19L8 5l5 14 M5 14h6 M16 11q5-3 5 2v6 M21 14q-6-2-6 2t6 1',leaf:'M12 21v-9 M12 13Q0 13 3 4q10-2 9 9 M12 16q0-13 9-12 3 11-9 12',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 6v6l4 2',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M15 15l6 6',down:'M12 3v13 M7 11l5 5 5-5 M4 19v3h16v-3',close:'M6 6l12 12 M18 6L6 18',end:'M3 12q9-9 18 0v5h-5v-5q-4-2-8 0v5H3z',captions:'M3 4h18v14H9l-5 4v-4H3z M7 9h10 M7 13h7',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3q0-7 8-7t8 7v3',send:'M3 3l19 9-19 9 4-9z M7 12h15',pause:'M8 5v14 M16 5v14',arrow:'M5 12h14 M14 7l5 5-5 5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const advisors=[{name:'Ms Lam',subject:'Science',symbol:'science',description:'Explore everyday science with fun examples.',topic:'Plant discoveries',hello:'Hello! I’m Ms Lam. Have you ever grown a plant?',follow:'How do you look after a plant?',question:'What do plants need to grow?',options:['Sunlight and water','Fizzy drinks','Sweets','Toys'],correct:0,explanation:'Plants use sunlight to make food and need water to grow. The right amount of each helps them stay healthy.',reflect:'Where could you put a plant so it gets enough light?',hint:'Think of a bright place, such as near a window.',done:'A bright spot near a window is a good choice. Keep checking the soil before watering. Well done exploring with me!'},{name:'Mr Chan',subject:'Maths',symbol:'math',description:'Understand maths, one clear step at a time.',topic:'Sharing fairly',hello:'Hello! I’m Mr Chan. What is your favourite fruit?',follow:'Imagine sharing six apples with three friends. How could you make it fair?',question:'6 apples shared by 3 people. How many each?',options:['1 apple','2 apples','3 apples','6 apples'],correct:1,explanation:'Six divided by three is two. Each person gets two apples, so everyone has an equal share.',reflect:'What if we shared eight apples between four people?',hint:'Try giving one apple to each person, then repeat.',done:'Eight divided by four is two, so each person gets two apples again. Great practice today!'},{name:'Ms May',subject:'English',symbol:'english',description:'Build your English skills through friendly chats.',topic:'Friendly greetings',hello:'Hello! I’m Ms May. What would you like me to call you?',follow:'Nice to meet you! What do you say when you meet someone in the morning?',question:'Which greeting do we use in the morning?',options:['Good night!','Goodbye!','Good morning!','Thank you!'],correct:2,explanation:'We say “Good morning!” when we meet someone in the morning. It is a friendly way to start the day.',reflect:'Try a greeting with a name, such as “Good morning, Ms May!”',hint:'Start with “Good morning”, then add a name.',done:'Thanks for practising! Keep saying your greeting aloud to build confidence. See you next time!'}];
let selected=0,session=false,phase='intro',turns=0,answered=null,transcript=[],last='',caption=true,ended=false,started=0,tick=null,speech=null,recognition=null,voiceToken=0,listening=false,speaking=false,historyOpen=true;
const $=s=>document.querySelector(s),app=$('#app'),advisor=()=>advisors[selected];
function avatar(i,small=false){return `<span class="avatar a${i} ${small?'tiny':''}" aria-hidden="true"></span>`}
function brand(){return `<div class="brand">${icon('book')}StudyMate</div>`}
function selectPage(){stopAudio();clearInterval(tick);session=false;app.className='';app.innerHTML=`<header>${brand()}<span class="descriptor">AI learning companion</span><nav class="steps" aria-label="Learning steps"><span class="active"><b>1</b>Choose an advisor</span><i></i><span><b>2</b>Start talking</span></nav></header><main class="choose"><div class="intro"><h1>Choose your academic advisor</h1><p>Pick an advisor and start a conversation.</p></div><div class="cards">${advisors.map((a,i)=>`<button class="advisor ${selected===i?'selected':''}" aria-pressed="${selected===i}" data-select="${i}">${selected===i?`<span class="selection">${icon('check')}</span>`:''}<div class="avatar a${i}" aria-hidden="true"></div><h2>${a.name}</h2><span class="badge">${icon(a.symbol)}${a.subject}</span><p>${a.description}</p></button>`).join('')}</div><div class="start"><button class="primary" id="start">${icon('mic')}Start conversation</button><p class="fine">Speak at your own pace. You can also type your answers.</p></div><p class="demo">Guided learning demo · Browser voice · No live AI connection</p></main>`;document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=+b.dataset.select;selectPage();$(`[data-select="${selected}"]`).focus()});$('#start').onclick=startSession;document.title='Choose your academic advisor · StudyMate'}
function startSession(){stopAudio();session=true;ended=false;phase='intro';turns=0;answered=null;transcript=[];caption=true;historyOpen=true;started=Date.now();app.className='session';const a=advisor();app.innerHTML=`<header>${brand()}<div class="header-advisor">${avatar(selected,true)}<span>${a.name}</span><span class="badge">${icon(a.symbol)}${a.subject}</span></div><div class="topic">${icon('leaf')}${a.topic}</div><button id="end" class="danger">${icon('end')}End conversation</button></header><main class="workspace"><section class="main-column" aria-label="Conversation with ${a.name}"><div class="stage ${selected===2?'other may':selected===1?'other':''}"><div class="scene" role="img" aria-label="${a.name} in a calm classroom"></div>${selected?`<div class="hero-avatar avatar a${selected}" aria-hidden="true"></div>`:''}<div class="presence"><span class="dot"></span><span id="presence-text">${a.name} · Ready</span></div><div class="timer">${icon('clock')}<span id="time">00:00</span></div><div class="subtitle" id="subtitle"><strong>${a.name}</strong><span id="caption-text"></span></div><section class="quiz" id="quiz" aria-label="Multiple-choice question" hidden></section><div class="summary" id="summary" hidden></div></div><div class="controls"><button class="primary" id="mic">${icon('mic')}Start speaking</button><button class="secondary" id="replay">${icon('speaker')}Replay</button><button class="secondary" id="captions" aria-pressed="true">${icon('captions')}Captions</button><button class="secondary history-toggle" id="show-history" aria-expanded="true">${icon('history')}History</button></div><p class="status" id="status" role="status">You can speak or type your answer.</p><form class="text-form" id="reply"><input id="answer-text" aria-label="Your answer" placeholder="Or type your answer…" maxlength="600" autocomplete="off"><button class="secondary" aria-label="Send answer">${icon('send')}Send</button></form><p class="demo">Guided learning demo · No live AI connection</p></section><aside class="history" aria-label="Conversation history"><div class="history-top"><h2>${icon('history')}Conversation history</h2><button id="hide-history" class="icon-button" aria-label="Hide conversation history">${icon('close')}</button></div><label class="search">${icon('search')}<input id="search" type="search" placeholder="Search conversation" aria-label="Search conversation"></label><div class="messages" id="messages" role="log" aria-label="Conversation messages"></div><button class="secondary latest" id="latest">${icon('down')}Back to latest</button><p class="history-note">Available during this session only</p></aside></main><dialog id="end-dialog"><h2>Finish for now?</h2><p>You can still read your conversation history after ending this session.</p><div class="dialog-actions"><button class="secondary" id="cancel-end">Keep talking</button><button class="danger" id="confirm-end">End conversation</button></div></dialog>`;
$('#end').onclick=()=>$('#end-dialog').showModal();$('#cancel-end').onclick=()=>$('#end-dialog').close();$('#confirm-end').onclick=()=>{$('#end-dialog').close();finish()};$('#mic').onclick=listen;$('#replay').onclick=()=>speak(last);$('#captions').onclick=()=>{caption=!caption;$('#captions').setAttribute('aria-pressed',String(caption));$('#subtitle').hidden=!caption||phase==='quiz'||ended};$('#reply').onsubmit=e=>{e.preventDefault();submit($('#answer-text').value)};$('#search').oninput=()=>renderHistory(false);$('#latest').onclick=()=>{$('#search').value='';renderHistory(true)};$('#hide-history').onclick=()=>toggleHistory(false);$('#show-history').onclick=()=>{toggleHistory(!historyOpen);if(historyOpen)document.querySelector('.history').scrollIntoView({block:'nearest'})};clearInterval(tick);tick=setInterval(()=>{if(!session||ended)return;const seconds=Math.floor((Date.now()-started)/1000);$('#time').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')},1000);say(a.hello);document.title=a.topic+' · StudyMate'}
function toggleHistory(open){historyOpen=open;app.classList.toggle('history-hidden',!open);$('#show-history').setAttribute('aria-expanded',String(open))}
function message(who,text){transcript.push({who,text,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});renderHistory(true)}
function renderHistory(scroll){const query=$('#search').value.toLowerCase().trim();const filtered=transcript.map((m,i)=>({...m,i})).filter(m=>m.text.toLowerCase().includes(query)||(m.who==='user'?'you':advisor().name.toLowerCase()).includes(query));$('#messages').innerHTML=filtered.length?filtered.map(m=>`<article class="message ${m.who==='user'?'user':''}">${m.who==='user'?`<span class="user-icon">${icon('user')}</span>`:avatar(selected,true)}<div class="message-body"><div class="message-meta"><strong>${m.who==='user'?'You':advisor().name}</strong><time>${m.time}</time>${m.who==='advisor'?`<button data-replay="${m.i}" aria-label="Replay message ${m.i+1}">${icon('speaker')}</button>`:''}</div><p>${esc(m.text)}</p></div></article>`).join(''):'<p class="no-results">No matching messages. Try a different word.</p>';document.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>speak(transcript[+b.dataset.replay].text));if(scroll&&!query)$('#messages').scrollTop=$('#messages').scrollHeight}
function status(text){if($('#status'))$('#status').textContent=text}
function voiceUI(){if(!session)return;$('#presence-text').textContent=advisor().name+' · '+(ended?'Session ended':listening?'Listening':speaking?'Speaking':'Your turn');document.querySelector('.stage').classList.toggle('talking',speaking);$('#mic').innerHTML=icon(listening?'pause':'mic')+(listening?'Stop listening':'Start speaking')}
function stopAudio(){voiceToken++;window.speechSynthesis?.cancel();if(recognition){recognition.onend=null;recognition.onerror=null;recognition.onresult=null;recognition.abort();recognition=null}listening=false;speaking=false;if(session)voiceUI()}
function say(text){last=text;message('advisor',text);$('#caption-text').textContent=text;speak(text)}
function speak(text){if(!text)return;stopAudio();if(!('speechSynthesis'in window)){status('Voice playback is not available here. You can read the captions and history.');return}const token=voiceToken;speech=new SpeechSynthesisUtterance(text);speech.lang='en-GB';speech.rate=.9;const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'));if(voice)speech.voice=voice;speech.onstart=()=>{if(token!==voiceToken)return;speaking=true;voiceUI();status('Your advisor is speaking. You can interrupt to answer.')};speech.onend=()=>{if(token!==voiceToken)return;speaking=false;voiceUI();status(ended?'Session ended. Your history is still available.':'Your turn. Speak or type your answer.')};speech.onerror=()=>{if(token!==voiceToken)return;speaking=false;voiceUI();status('Audio could not play. Try Replay, or read the captions.')};speechSynthesis.speak(speech)}
function showQuiz(){phase='quiz';answered=null;$('#subtitle').hidden=true;$('#quiz').hidden=false;const a=advisor();$('#quiz').innerHTML=`<div class="quiz-head"><span class="quiz-tag">Let’s think</span><h2>${a.question}</h2></div><div class="options">${a.options.map((o,i)=>`<button class="option" data-option="${i}"><span class="letter">${'ABCD'[i]}</span>${esc(o)}</button>`).join('')}</div><p class="feedback" id="feedback" aria-live="polite">Choose an answer or tell your advisor.</p><button class="secondary next" id="continue" hidden>Continue conversation ${icon('arrow')}</button>`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>chooseAnswer(+b.dataset.option));$('#continue').onclick=()=>{phase='reflect';$('#quiz').hidden=true;$('#subtitle').hidden=!caption;say(a.reflect)};say(a.question)}
function chooseAnswer(i){if(answered!==null||phase!=='quiz'||ended)return;answered=i;const a=advisor();message('user',`${'ABCD'[i]}. ${a.options[i]}`);document.querySelectorAll('[data-option]').forEach(b=>{b.disabled=true;b.classList.toggle('correct',+b.dataset.option===a.correct);b.classList.toggle('wrong',+b.dataset.option===i&&i!==a.correct)});const text=(i===a.correct?'That’s right! ':'Not quite. The answer is '+a.options[a.correct]+'. ')+a.explanation;$('#feedback').textContent=text;$('#continue').hidden=false;say(text)}
function submit(raw){const text=raw.trim();if(!text||ended)return;$('#answer-text').value='';stopAudio();if(phase==='quiz'){if(answered!==null){status('Choose Continue conversation to move on.');return}let clean=text.toLowerCase().replace(/[.!?]/g,'').trim();let idx=advisor().options.findIndex(o=>o.toLowerCase().replace(/[.!?]/g,'')===clean);if(idx<0){const match=clean.match(/^(?:option |answer )?([abcd])$/);if(match)idx='abcd'.indexOf(match[1])}if(idx>=0){chooseAnswer(idx);return}message('user',text);status('Please choose A, B, C or D, or tap an answer.');return}message('user',text);if(/\b(help|hint|don't know|not sure)\b/i.test(text)){say(phase==='reflect'?advisor().hint:'There is no wrong answer here. Tell me a little about your experience.');return}if(phase==='intro'){turns++;if(turns===1)say('Thank you for sharing! '+advisor().follow);else showQuiz()}else if(phase==='reflect'){phase='wrap';say(advisor().done);status('You have finished today’s practice. End the conversation when you are ready.')}else say('You have completed this guided activity. Choose End conversation to finish, or start another subject.')}
function listen(){if(ended)return;if(listening){recognition?.stop();return}const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){status('Speech recognition is not supported in this browser. Please type your answer below.');$('#answer-text').focus();return}stopAudio();const token=voiceToken;const r=new R();recognition=r;r.lang='en-GB';r.interimResults=false;r.continuous=false;r.onstart=()=>{if(token!==voiceToken)return;listening=true;voiceUI();status('Listening… Speak in English, then pause.')};r.onresult=e=>{if(token!==voiceToken)return;submit(e.results[0][0].transcript)};r.onerror=e=>{if(token!==voiceToken)return;status(e.error==='not-allowed'?'Microphone access was not allowed. Enable it in your browser or type below.':e.error==='no-speech'?'No speech detected. Please try again or type below.':'Speech recognition is unavailable. Please type your answer below.')};r.onend=()=>{if(token!==voiceToken)return;listening=false;recognition=null;voiceUI();if($('#status').textContent.startsWith('Listening'))status('No answer received. Try again or type below.')};try{r.start()}catch{status('Could not start the microphone. Please type your answer below.')}}
function finish(){stopAudio();ended=true;clearInterval(tick);voiceUI();$('#end').disabled=true;$('#mic').disabled=true;$('#reply').hidden=true;$('#quiz').hidden=true;$('#subtitle').hidden=true;$('#summary').hidden=false;$('#summary').innerHTML=`<div>${icon('check')}<h2>Thanks for learning with me!</h2><p>You explored ${advisor().topic.toLowerCase()}. Your conversation is still available on the right.</p><button class="primary" id="again">Practise again</button><button class="secondary" id="change">Choose another advisor</button></div>`;$('#again').onclick=startSession;$('#change').onclick=selectPage;status('Session ended. Choose an activity to start again.')}
window.addEventListener('pagehide',()=>{stopAudio();clearInterval(tick)});selectPage();
